// Gera o mapaAgentes e a lista agentesExcluidos para colar no nó Config do fluxo principal.
// Casamento em cascata: e-mail -> login -> nome normalizado -> AJUSTES manuais.

const FILA_EXCLUIDA = '87';   // id da fila cujos agentes não geram protocolo (ex.: cobrança)
// Ajustes para quem não casa sozinho: { '<agente telefonia>': { r: '<responsável>', t: '<equipe>' } }
const AJUSTES = {};

const email = (s) => String(s || '').trim().toLowerCase();
const chave = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');
const equipe = (a) => { const t = (a.teams && typeof a.teams === 'object') ? Object.keys(a.teams) : []; return t.length ? String(t[0]) : ''; };

// A telefonia é paginada: junta TODAS as páginas (uma página só = agentes sumindo do mapa).
let telefonia = [];
for (const pagina of $('Agentes Telefonia').all().map(i => i.json)) {
  telefonia = telefonia.concat(Array.isArray(pagina) ? pagina : (pagina.data || []));
}
const resp = $('Agentes Helpdesk').all().map(i => i.json);
const helpdesk = (resp.length === 1 && Array.isArray(resp[0])) ? resp[0] : resp;

const porEmail = {}, porLogin = {}, porNome = {};
for (const a of helpdesk) {
  if (a.status_id && String(a.status_id) !== '2') continue;   // só agentes ativos
  const alvo = { r: String(a.id), t: equipe(a) };
  if (a.email) porEmail[email(a.email)] = alvo;
  if (a.username) porLogin[chave(a.username)] = alvo;
  const nome = a.fullname || a.title;
  if (nome) porNome[chave(nome)] = alvo;
}

const mapaAgentes = {}, semMatch = [];
for (const a of telefonia) {
  if (a.archived) continue;
  const achado = AJUSTES[a.id]
    || (a.email && porEmail[email(a.email)])
    || (a.login && porLogin[chave(a.login)])
    || (a.name && porNome[chave(a.name)])
    || null;
  if (achado && achado.r) mapaAgentes[String(a.id)] = { r: achado.r, t: achado.t || '' };
  else semMatch.push({ id: a.id, nome: a.name });
}

const agentesExcluidos = telefonia
  .filter(a => !a.archived && Array.isArray(a.queues) && a.queues.map(String).includes(FILA_EXCLUIDA))
  .map(a => String(a.id));

return [{ json: { mapeados: Object.keys(mapaAgentes).length, sem_match: semMatch, mapaAgentes, agentesExcluidos } }];
